// frontend-project/src/components/Reports.js
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import toast from 'react-hot-toast';
import { FaChartBar, FaPrint, FaDownload, FaFilePdf, FaFileExcel } from 'react-icons/fa';

const Reports = () => {
  const [reportType, setReportType] = useState('monthly');
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
  const [employeeNumber, setEmployeeNumber] = useState('');
  const [reportData, setReportData] = useState(null);
  const [departmentSummary, setDepartmentSummary] = useState(null);
  const [yearlyData, setYearlyData] = useState(null);
  const [employeeHistory, setEmployeeHistory] = useState(null);
  const [loading, setLoading] = useState(false);
  const [employees, setEmployees] = useState([]);

  const months = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      const response = await axios.get('/employees/all');
      setEmployees(response.data || []);
    } catch (error) {
      console.error('Failed to fetch employees:', error);
      setEmployees([]);
    }
  };

  const fetchMonthlyReport = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`/reports/monthly-payroll?year=${selectedYear}&month=${selectedMonth}`);
      setReportData(response.data);
      setDepartmentSummary(null);
      setYearlyData(null);
      setEmployeeHistory(null);
      toast.success('Monthly report generated successfully');
    } catch (error) {
      toast.error('Failed to fetch monthly report');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchDepartmentSummary = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/reports/department-summary');
      setDepartmentSummary(response.data);
      setReportData(null);
      setYearlyData(null);
      setEmployeeHistory(null);
      toast.success('Department summary generated successfully');
    } catch (error) {
      toast.error('Failed to fetch department summary');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchYearlySummary = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`/reports/yearly-summary?year=${selectedYear}`);
      setYearlyData(response.data);
      setReportData(null);
      setDepartmentSummary(null);
      setEmployeeHistory(null);
      toast.success('Yearly summary generated successfully');
    } catch (error) {
      toast.error('Failed to fetch yearly summary');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployeeHistory = async () => {
    if (!employeeNumber) {
      toast.error('Please select an employee');
      return;
    }
    setLoading(true);
    try {
      const response = await axios.get(`/reports/employee-history/${employeeNumber}`);
      setEmployeeHistory(response.data);
      setReportData(null);
      setDepartmentSummary(null);
      setYearlyData(null);
      toast.success('Employee history retrieved successfully');
    } catch (error) {
      toast.error('Failed to fetch employee history');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateReport = () => {
    if (reportType === 'monthly') {
      fetchMonthlyReport();
    } else if (reportType === 'department') {
      fetchDepartmentSummary();
    } else if (reportType === 'yearly') {
      fetchYearlySummary();
    } else if (reportType === 'employee') {
      fetchEmployeeHistory();
    }
  };

  const handlePrint = () => {
    window.print();
  };

  if (loading && !reportData && !departmentSummary && !yearlyData && !employeeHistory) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="text-center">
          <div className="loading-spinner mx-auto mb-4"></div>
          <p className="text-gray-600">Generating report...</p>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Reports & Analytics</h2>
          <p className="text-gray-600 mt-1">View payroll reports and department analytics</p>
        </div>
        {reportData && (
          <button onClick={handlePrint} className="btn-secondary flex items-center gap-2">
            <FaPrint /> Print Report
          </button>
        )}
      </div>

      <div className="card mb-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Report Type</label>
            <select
              value={reportType}
              onChange={(e) => setReportType(e.target.value)}
              className="input-field"
            >
              <option value="monthly">Monthly Payroll Report</option>
              <option value="department">Department Summary</option>
              <option value="yearly">Yearly Summary Report</option>
              <option value="employee">Employee Salary History</option>
            </select>
          </div>

          {reportType === 'monthly' && (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Year</label>
                <input
                  type="number"
                  value={selectedYear}
                  onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                  className="input-field"
                  min="2020"
                  max="2030"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Month</label>
                <select
                  value={selectedMonth}
                  onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                  className="input-field"
                >
                  {months.map((month, index) => (
                    <option key={index} value={index + 1}>{month}</option>
                  ))}
                </select>
              </div>
            </>
          )}

          {reportType === 'yearly' && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Year</label>
              <input
                type="number"
                value={selectedYear}
                onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                className="input-field"
                min="2020"
                max="2030"
              />
            </div>
          )}

          {reportType === 'employee' && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Employee</label>
              <select
                value={employeeNumber}
                onChange={(e) => setEmployeeNumber(e.target.value)}
                className="input-field"
              >
                <option value="">Select Employee</option>
                {employees.map((emp) => (
                  <option key={emp._id} value={emp.employeeNumber}>
                    {emp.employeeNumber} - {emp.firstName} {emp.lastName} ({emp.position})
                  </option>
                ))}
              </select>
            </div>
          )}

          <div className="flex items-end">
            <button
              onClick={handleGenerateReport}
              className="btn-primary w-full flex items-center justify-center gap-2"
            >
              <FaChartBar /> Generate Report
            </button>
          </div>
        </div>
      </div>

      {/* Monthly Payroll Report */}
      {reportData && !loading && (
        <div className="card">
          <h3 className="text-xl font-bold mb-2">
            Monthly Payroll Report - {months[reportData.month - 1]} {reportData.year}
          </h3>
          <p className="text-gray-600 mb-6">Employee Payroll Summary (First Name, Last Name, Position, Department, Net Salary)</p>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
            <div className="bg-blue-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Employees</p>
              <p className="text-2xl font-bold text-blue-600">{reportData.summary.totalEmployees}</p>
            </div>
            <div className="bg-green-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Net Payroll</p>
              <p className="text-2xl font-bold text-green-600">{reportData.summary.totalNetPayroll.toLocaleString()} RWF</p>
            </div>
            <div className="bg-yellow-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Gross Payroll</p>
              <p className="text-2xl font-bold text-yellow-600">{reportData.summary.totalGrossPayroll.toLocaleString()} RWF</p>
            </div>
            <div className="bg-red-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Deductions</p>
              <p className="text-2xl font-bold text-red-600">{reportData.summary.totalDeductions.toLocaleString()} RWF</p>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">First Name</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Last Name</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Position</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Department</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Gross Salary</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Deductions</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Net Salary</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {reportData.report.map((record, index) => (
                  <tr key={index} className="hover:bg-gray-50">
                    <td className="px-6 py-4 text-sm text-gray-900">{record.firstName}</td>
                    <td className="px-6 py-4 text-sm text-gray-900">{record.lastName}</td>
                    <td className="px-6 py-4 text-sm text-gray-600">{record.position}</td>
                    <td className="px-6 py-4 text-sm text-gray-600">{record.department}</td>
                    <td className="px-6 py-4 text-sm text-gray-900">{record.grossSalary.toLocaleString()} RWF</td>
                    <td className="px-6 py-4 text-sm text-red-600">{record.deductions.toLocaleString()} RWF</td>
                    <td className="px-6 py-4 text-sm text-green-600 font-semibold">{record.netSalary.toLocaleString()} RWF</td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-gray-50">
                <tr>
                  <td colSpan="4" className="px-6 py-3 text-right font-semibold">Totals:</td>
                  <td className="px-6 py-3 font-semibold">{reportData.summary.totalGrossPayroll.toLocaleString()} RWF</td>
                  <td className="px-6 py-3 font-semibold">{reportData.summary.totalDeductions.toLocaleString()} RWF</td>
                  <td className="px-6 py-3 font-semibold">{reportData.summary.totalNetPayroll.toLocaleString()} RWF</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      )}

      {/* Department Summary */}
      {departmentSummary && !loading && (
        <div className="card">
          <h3 className="text-xl font-bold mb-4">Department Salary Summary</h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
            {departmentSummary.map((dept, index) => (
              <div key={index} className="bg-gradient-to-r from-blue-50 to-indigo-50 p-4 rounded-lg">
                <h4 className="font-semibold text-lg text-gray-800 mb-2">{dept.departmentName} ({dept.departmentCode})</h4>
                <div className="space-y-1">
                  <p className="text-sm text-gray-600">Employees: <span className="font-semibold">{dept.employeeCount}</span></p>
                  <p className="text-sm text-gray-600">Base Gross Salary: <span className="font-semibold">{dept.baseGrossSalary.toLocaleString()} RWF</span></p>
                  <p className="text-sm text-gray-600">Base Deduction: <span className="font-semibold">{dept.baseDeduction.toLocaleString()} RWF</span></p>
                  <p className="text-sm text-gray-600">Total Payroll Processed: <span className="font-semibold text-green-600">{dept.totalPayrollProcessed.toLocaleString()} RWF</span></p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Yearly Summary */}
      {yearlyData && !loading && (
        <div className="card">
          <h3 className="text-xl font-bold mb-4">Yearly Summary Report - {yearlyData.year}</h3>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
            <div className="bg-purple-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Employees Processed</p>
              <p className="text-2xl font-bold text-purple-600">{yearlyData.yearlyTotal.totalEmployeesProcessed}</p>
            </div>
            <div className="bg-green-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Yearly Net Payroll</p>
              <p className="text-2xl font-bold text-green-600">{yearlyData.yearlyTotal.totalNetSalary.toLocaleString()} RWF</p>
            </div>
            <div className="bg-blue-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Yearly Gross Payroll</p>
              <p className="text-2xl font-bold text-blue-600">{yearlyData.yearlyTotal.totalGrossSalary.toLocaleString()} RWF</p>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Month</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Employees</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Gross Salary</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Deductions</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Net Salary</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {yearlyData.monthlyData.map((data, index) => (
                  <tr key={index} className="hover:bg-gray-50">
                    <td className="px-6 py-4 text-sm font-semibold text-gray-900">{months[data.month - 1]}</td>
                    <td className="px-6 py-4 text-sm text-gray-600">{data.totalEmployees}</td>
                    <td className="px-6 py-4 text-sm text-gray-900">{data.totalGrossSalary.toLocaleString()} RWF</td>
                    <td className="px-6 py-4 text-sm text-red-600">{data.totalDeductions.toLocaleString()} RWF</td>
                    <td className="px-6 py-4 text-sm text-green-600 font-semibold">{data.totalNetSalary.toLocaleString()} RWF</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Employee History */}
      {employeeHistory && !loading && (
        <div className="card">
          <h3 className="text-xl font-bold mb-2">Employee Salary History</h3>
          <p className="text-gray-600 mb-4">
            {employeeHistory.employee.firstName} {employeeHistory.employee.lastName} - {employeeHistory.employee.employeeNumber}
          </p>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
            <div className="bg-blue-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Months Processed</p>
              <p className="text-2xl font-bold text-blue-600">{employeeHistory.summary.monthsProcessed}</p>
            </div>
            <div className="bg-green-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Earned</p>
              <p className="text-2xl font-bold text-green-600">{employeeHistory.summary.totalEarned.toLocaleString()} RWF</p>
            </div>
            <div className="bg-yellow-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Gross</p>
              <p className="text-2xl font-bold text-yellow-600">{employeeHistory.summary.totalGross.toLocaleString()} RWF</p>
            </div>
            <div className="bg-red-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Deductions</p>
              <p className="text-2xl font-bold text-red-600">{employeeHistory.summary.totalDeductions.toLocaleString()} RWF</p>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Period</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Gross Salary</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Deductions</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Net Salary</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Payment Date</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {employeeHistory.salaryHistory.map((salary, index) => (
                  <tr key={index} className="hover:bg-gray-50">
                    <td className="px-6 py-4 text-sm text-gray-900">
                      {months[salary.month - 1]} {salary.year}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900">{salary.grossSalary.toLocaleString()} RWF</td>
                    <td className="px-6 py-4 text-sm text-red-600">{salary.totalDeduction.toLocaleString()} RWF</td>
                    <td className="px-6 py-4 text-sm text-green-600 font-semibold">{salary.netSalary.toLocaleString()} RWF</td>
                    <td className="px-6 py-4 text-sm text-gray-600">{new Date(salary.paymentDate).toLocaleDateString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default Reports;
